    for ki in range(K // (S * BK)):
        # Descriptors use zero padding for rows beyond irregular M/N.
        w = WD.load([n0, k0 + ki * BK])
        x = XD.load([m0, k0 + ki * BK])
        acc = tl.dot(w, x.T, acc)
